const CSS=`<style>
*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;color:#211b1c;background:linear-gradient(#fff9f5ed,#fffdfded),url(${BG}) center/cover fixed}header{display:flex;align-items:center;gap:16px;padding:14px 22px;background:linear-gradient(100deg,#970612,#ef1e2d);color:#fff;box-shadow:0 5px 20px #7d061833;position:relative;z-index:5}header img{width:82px;height:82px;border-radius:50%;background:#fff;object-fit:contain}header b{display:block;font-size:32px}header small{display:block;font-size:18px;margin-top:3px}.card{max-width:570px;margin:28px auto;background:#fff;border-radius:22px;padding:24px;box-shadow:0 10px 35px #6f101b22}h1{color:#c71925;text-align:center}label{display:block;font-weight:700;margin:15px 0 6px}input,button{width:100%;padding:14px;border-radius:12px;border:1px solid #d9bfc2;font-size:16px}button{background:#c71925;color:#fff;font-weight:800;border:0;margin-top:15px;cursor:pointer}.success,.err,.msg{margin-top:15px;padding:14px;border-radius:12px}.success{background:#e9f8ed}.err{background:#ffe7e7;color:#980710}.msg{background:#fff3de}.otp{font-size:35px;letter-spacing:8px;color:#c71925;font-weight:900;text-align:center;padding:12px}.small{font-size:14px}.game{max-width:1000px;margin:24px auto;padding:0 14px}.hero{text-align:center}.hero h1{margin-bottom:4px}.hero p{font-weight:700}.stage{text-align:center;color:#c71925;font-weight:900;font-size:18px;margin:20px 0}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.gift{aspect-ratio:1;border-radius:50%;overflow:hidden;position:relative;background:#fff;border:6px solid #fff;box-shadow:0 8px 24px #6f101b22,0 0 0 5px var(--ring,#c71925) inset;display:flex;align-items:center;justify-content:center;text-align:center;transition:transform .2s,box-shadow .2s}.gift:hover{transform:scale(1.02);box-shadow:0 10px 30px #6f101b33,0 0 0 5px var(--ring,#c71925) inset}.gift img{width:100%;height:100%;object-fit:contain;padding:8px;background:linear-gradient(145deg,#fff,#fff8f4);filter:saturate(1.04) contrast(1.02)}.gift b{position:absolute;bottom:7px;left:7px;right:7px;background:#b90d18e8;color:#fff;padding:8px 6px;border-radius:999px;font-size:12px;line-height:1.15}.closed{font-size:34px;background:radial-gradient(circle at 35% 25%,#ff5c62,#c71925 55%,#79040d 100%);border:6px solid #fff;box-shadow:0 8px 24px #6f101b33,0 0 0 7px var(--ring,#c71925) inset,0 0 0 2px #fff inset}.closed span{font-weight:1000;color:#fff;text-shadow:0 3px 10px #520008}.mega{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;padding:10px;background:linear-gradient(145deg,#fff9d8,#ffe16a)}.mega img{width:100%;height:100%;object-fit:cover;border-radius:7px;padding:0}.mega b{position:static;grid-column:1/-1;background:#9a0711}.shuffle .gift{animation:sh .22s infinite alternate}@keyframes sh{from{transform:translateY(-5px) rotate(-2deg)}to{transform:translateY(5px) rotate(2deg)}}
.winner{grid-column:1/-1;min-height:760px;background:radial-gradient(circle at 50% 23%,#fff 0,#fff7df 23%,transparent 44%),linear-gradient(135deg,#fff7e7 0%,#ffe5c4 48%,#fff7ec 100%);border:4px solid #e7aa1f;border-radius:30px;padding:20px 18px 30px;text-align:center;color:#7f0710;box-shadow:0 20px 65px #8b111644;position:relative;overflow:hidden}.winner:before{content:"";position:absolute;inset:-30%;background:repeating-conic-gradient(from 0deg,#f3b92f16 0deg 7deg,transparent 7deg 15deg);animation:spinburst 18s linear infinite;pointer-events:none}.winner:after{content:"";position:absolute;inset:0;background:radial-gradient(circle at 12% 25%,#e31b2340 0 4px,transparent 5px),radial-gradient(circle at 86% 30%,#e9aa243d 0 5px,transparent 6px),radial-gradient(circle at 20% 76%,#e31b2335 0 4px,transparent 5px),radial-gradient(circle at 82% 78%,#e9aa2435 0 5px,transparent 6px);background-size:130px 130px;pointer-events:none}.winnerTop{position:relative;z-index:2}.winnerTop .crown{font-size:54px;line-height:1;margin-top:-5px}.winnerTop .congrats{margin:0 0 8px;font-size:clamp(36px,9vw,76px);font-weight:1000;letter-spacing:-2px;background:linear-gradient(#ffe56d 0%,#f6b51e 38%,#e62932 48%,#970711 78%);-webkit-background-clip:text;background-clip:text;color:transparent;-webkit-text-stroke:2px #9a0711;text-shadow:0 4px 0 #fff,0 9px 18px #7c061044}.winnerRibbon{display:inline-block;background:linear-gradient(180deg,#f02a36,#a40612);color:#fff;border:4px solid #f4b52d;border-radius:16px;padding:9px 24px;font-size:clamp(22px,5.5vw,38px);font-weight:1000;box-shadow:0 9px 20px #8d071044;position:relative}.winnerRibbon:before,.winnerRibbon:after{content:"★";margin:0 14px;color:#ffd34f}.winnerProduct{position:relative;z-index:2;margin:24px auto 14px;max-width:760px;min-height:290px;border:4px solid #f0b52b;border-radius:28px;background:radial-gradient(circle at 50% 42%,#fff 0,#fffdf7 38%,#ffeac8 100%);box-shadow:inset 0 0 55px #f0b82a35,0 12px 28px #7c061033;display:flex;align-items:center;justify-content:center;gap:18px;padding:26px 22px;position:relative}.winnerProduct:before{content:"✦  ✧  ✦  ✧  ✦";position:absolute;top:8px;left:0;right:0;color:#e9ae24;font-size:18px;letter-spacing:8px}.winnerProduct img{width:min(46%,310px);height:270px;object-fit:contain;filter:drop-shadow(0 16px 12px #7c061044)}.winnerProduct img:only-child{width:min(78%,460px)}.winnerPrize{position:relative;z-index:2;background:linear-gradient(180deg,#ed2633,#a20712);color:#fff9ed;border:4px solid #f2b82b;border-radius:20px;padding:15px 18px;font-size:clamp(22px,5.8vw,40px);font-weight:1000;box-shadow:0 9px 20px #8d071044;text-shadow:0 2px 3px #7d0005}.winnerCollect{position:relative;z-index:2;margin:18px auto 0;max-width:700px;background:#fff6ed;border:2px solid #efc67a;border-radius:20px;padding:14px 18px;font-size:20px;font-weight:700;color:#7d2020}.winnerThanks{position:relative;z-index:2;margin:16px auto 0;max-width:700px;background:#fff0b8;border:2px solid #efca52;border-radius:20px;padding:14px;font-size:22px;font-weight:900;color:#9b0d18}.winnerStars{position:absolute;inset:0;pointer-events:none;background-image:radial-gradient(circle,#f7c53c 1px,transparent 2px);background-size:36px 36px;opacity:.2;animation:twinkle 1.8s ease-in-out infinite alternate}@keyframes twinkle{from{opacity:.08}to{opacity:.3}}@keyframes spinburst{to{transform:rotate(360deg)}}.hidden{display:none!important}@media(max-width:600px){header{padding:10px 14px;gap:10px}header img{width:62px;height:62px}header b{font-size:25px}header small{font-size:15px}.grid{gap:9px}.gift{border-width:5px}.gift img{padding:8px}.gift b{font-size:9px;padding:5px}.card{margin:18px 12px}.winner{min-height:650px;padding:14px 10px 22px}.winnerProduct{min-height:235px;padding:18px 10px}.winnerProduct img{height:210px}.winnerTop .congrats{-webkit-text-stroke:1px #9a0711}}
</style>`;

function tierFor(a){
 if(a<10000)return {tier:"₹5,000–₹9,999",gifts:["Libra Mug + Planet G Key Chain"]};
 if(a<20000)return {tier:"₹10,000–₹19,999",gifts:["6 Glass Set","Hot Box"]};
 if(a<35000)return {tier:"₹20,000–₹34,999",gifts:["Hot Box + Neckband","Red Chef Cook & Serve","Hot Box + Libra Coffee Mug"]};
 if(a<=60000)return {tier:"₹35,000–₹60,000",gifts:["Red Chef Cook & Serve","Signatize Bluetooth Speaker","Neckband"]};
 if(a<100000)return {tier:"₹60,001–₹99,999",gifts:["Red Chef Cook & Serve + 6 Piece Glass Set","Red Chef Hot & Cold – Steelo + Libra Coffee Mug","9 Piece Dinner Set"]};
 return {tier:"₹1,00,000+",gifts:["Red Chef Hot & Cold – Steelo","24 Piece Dinner Set","Red Chef Cook & Serve + Hot Box","Neckband + Hot Box"]};
}
const STAFF_HTML=`<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Planet G Staff Portal</title>${CSS}</head><body>
<header><img src="${LOGO}"><div><b>PLANET G</b><small>Staff Portal • Dasara 2026</small></div></header>
<main class="card">
<h1>Generate Customer OTP</h1><p>Enter the bill details. <b>Do not show the bill value or tier to the customer.</b></p>
<label>Customer Name</label><input id="name" placeholder="Customer name">
<label>Mobile Number</label><input id="mobile" inputmode="numeric" maxlength="10" placeholder="10-digit mobile number">
<label>Bill Number</label><input id="bill" placeholder="Bill number">
<label>Bill Value (₹)</label><input id="amount" inputmode="decimal" placeholder="e.g. 27500">
<button onclick="createSession()">GENERATE CUSTOMER OTP</button><div id="out"></div>
</main>
<script>
async function createSession(){
 const elName=document.getElementById('name'),elMobile=document.getElementById('mobile'),elBill=document.getElementById('bill'),elAmount=document.getElementById('amount'),elOut=document.getElementById('out');
 const body={customerName:elName.value.trim(),mobile:elMobile.value.trim(),billNumber:elBill.value.trim(),billValue:Number(elAmount.value.replace(/,/g,''))};
 elOut.innerHTML='<div class="msg">Creating OTP…</div>';
 try{const r=await fetch('/api/staff/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.error||'Unable to generate OTP.');elOut.innerHTML='<div class="success"><div>Customer OTP</div><div class="otp">'+d.otp+'</div><b>Give this OTP to the customer.</b><p class="small">Customer must enter the same mobile number + this OTP.</p><p class="small">Eligible tier: <b>'+d.tier+'</b></p></div>'}catch(e){elOut.innerHTML='<div class="err">'+(e.message||'Unable to generate OTP. Please try again.')+'</div>'}
}
</script></body></html>`;

const PLAY_HTML=`<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Planet G Dasara Gift Game</title>${CSS}</head><body>
<header><img src="${LOGO}"><div><b>PLANET G</b><small>Dasara 2026 Gift Game</small></div></header>
<main class="card" id="login"><h1>🎁 Your Dasara Surprise</h1><p style="text-align:center;font-weight:800">Thank You For Your Trust ❤️</p>
<label>Mobile Number</label><input id="mobile" inputmode="numeric" maxlength="10" placeholder="10-digit mobile number">
<label>OTP</label><input id="otp" inputmode="numeric" maxlength="6" placeholder="6-digit OTP">
<button onclick="verify()">UNLOCK MY GIFT GAME</button><div id="msg"></div></main>
<main class="game hidden" id="game"><div class="hero"><h1>🎊 Your Dasara Surprise Awaits! 🎊</h1><p>Every Planet G customer deserves a little surprise.</p></div><div id="stage"></div><div id="grid" class="grid"></div><button id="next" onclick="closeShuffle()">CLOSE CARDS & START SHUFFLE</button><div id="result"></div></main>
<script>
const IMG=${JSON.stringify(IMG)};
const RINGS=['#e31b23','#f28c28','#f2c230','#e84d8a','#8d4de8','#3378e8','#20a7a0','#38a84a','#d43b9c'];
const products=[['Libra Mug + Key Chain','mug.jpg'],['6 Glass Set','glass.jpg'],['Hot Box','hotbox.jpg'],['Hot Box + Neckband','neckband.jpg'],['Red Chef Cook & Serve','cook.jpg'],['Hot Box + Libra Mug','hotbox_mug.jpg'],['Signatize Bluetooth Speaker','speaker.jpg'],['9 Piece Dinner Set','larah.jpg'],['MEGA GIFT COMBO','mega.jpg']];
let sessionToken='',locked=false;
window.addEventListener('DOMContentLoaded',()=>{['mobile','otp'].forEach(id=>{const el=document.getElementById(id);if(el){el.addEventListener('focus',startFestivalMusic,{once:false});el.addEventListener('input',startFestivalMusic,{once:false});}});});
function tile(i,closed=false){if(closed)return '<div class="gift closed" style="--ring:'+RINGS[i]+'" onclick="choose('+i+')"><span>G</span></div>';if(i===8)return '<div class="gift mega">'+['mug.jpg','glass.jpg','hotbox.jpg','cook.jpg','neckband.jpg','speaker.jpg','steelo.jpg','viva.jpg'].map(x=>'<img src="'+IMG[x]+'">').join('')+'<b>MEGA GIFT COMBO</b></div>';return '<div class="gift" style="--ring:'+RINGS[i]+'"><img src="'+IMG[products[i][1]]+'"><b>'+products[i][0]+'</b></div>'}
function prizeImages(prize){const m={'Libra Mug + Planet G Key Chain':['mug.jpg'],'6 Glass Set':['glass.jpg'],'Hot Box':['hotbox.jpg'],'Hot Box + Neckband':['hotbox.jpg','neckband.jpg'],'Red Chef Cook & Serve':['cook.jpg'],'Hot Box + Libra Coffee Mug':['hotbox.jpg','mug.jpg'],'Signatize Bluetooth Speaker':['speaker.jpg'],'Neckband':['neckband.jpg'],'Red Chef Cook & Serve + 6 Piece Glass Set':['cook.jpg','glass.jpg'],'Red Chef Hot & Cold – Steelo + Libra Coffee Mug':['steelo.jpg','mug.jpg'],'9 Piece Dinner Set':['larah.jpg'],'24 Piece Dinner Set':['viva.jpg'],'Red Chef Hot & Cold – Steelo':['steelo.jpg'],'Red Chef Cook & Serve + Hot Box':['cook.jpg','hotbox.jpg'],'Neckband + Hot Box':['neckband.jpg','hotbox.jpg']};return m[prize]||['mega.jpg']}
function render(closed=false){grid.innerHTML='';for(let i=0;i<9;i++)grid.insertAdjacentHTML('beforeend',tile(i,closed))}
async function verify(){startFestivalMusic();const elMobile=document.getElementById('mobile'),elOtp=document.getElementById('otp'),elMsg=document.getElementById('msg'),elLogin=document.getElementById('login'),elGame=document.getElementById('game'),elStage=document.getElementById('stage');const m=elMobile.value.replace(/\D/g,''),o=elOtp.value.trim();if(m.length!==10||o.length!==6){elMsg.innerHTML='<div class="err">Enter your 10-digit mobile number and 6-digit OTP.</div>';return}try{const r=await fetch('/api/customer/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mobile:m,otp:o})});const d=await r.json();if(!r.ok)throw Error(d.error||'Incorrect or expired OTP.');sessionToken=d.token;elLogin.classList.add('hidden');elGame.classList.remove('hidden');elStage.textContent='First, take a look at all 9 gifts…';render(false)}catch(e){elMsg.innerHTML='<div class="err">'+(e.message||'Unable to verify OTP.')+'</div>'}}
function closeShuffle(){render(true);document.getElementById('stage').textContent='🔀 Shuffling your surprise…';document.getElementById('next').style.display='none';const g=document.getElementById('grid');g.classList.add('shuffle');shuffleSound();let swaps=0;const swapTimer=setInterval(()=>{const cards=[...g.children];if(cards.length<2)return;let a=Math.floor(Math.random()*cards.length),b=Math.floor(Math.random()*cards.length);while(b===a)b=Math.floor(Math.random()*cards.length);const ca=cards[a],cb=cards[b];if(a<b)g.insertBefore(cb,ca);else g.insertBefore(ca,cb);swaps++;if(swaps>=22){clearInterval(swapTimer);g.classList.remove('shuffle');document.getElementById('stage').textContent='Choose ANY one closed card.'}},120)}
function startFestivalMusic(){try{const A=window.AudioContext||window.webkitAudioContext;if(!A)return;if(window.pgMusic){if(window.pgMusic.state==='suspended')window.pgMusic.resume();return}const c=new A();window.pgMusic=c;const master=c.createGain();master.gain.value=.18;master.connect(c.destination);const bpm=140,step=60/bpm;const melody=[523.25,659.25,783.99,1046.5,880,783.99,659.25,783.99,1174.66,1046.5,880,783.99,659.25,783.99,1046.5,1318.51];const bass=[130.81,164.81,196,164.81];let n=0;const tick=()=>{if(c.state==='closed')return;const t=c.currentTime;const f=melody[n%melody.length];let o=c.createOscillator(),g=c.createGain();o.type='square';o.frequency.value=f;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.055,t+.008);g.gain.exponentialRampToValueAtTime(.0001,t+step*.72);o.connect(g);g.connect(master);o.start(t);o.stop(t+step*.75);if(n%2===0){let b=c.createOscillator(),bg=c.createGain();b.type='sawtooth';b.frequency.value=bass[(n/2)%bass.length|0];bg.gain.setValueAtTime(.0001,t);bg.gain.exponentialRampToValueAtTime(.065,t+.01);bg.gain.exponentialRampToValueAtTime(.0001,t+step*.9);b.connect(bg);bg.connect(master);b.start(t);b.stop(t+step);let k=c.createOscillator(),kg=c.createGain();k.type='sine';k.frequency.setValueAtTime(150,t);k.frequency.exponentialRampToValueAtTime(55,t+.09);kg.gain.setValueAtTime(.11,t);kg.gain.exponentialRampToValueAtTime(.0001,t+.12);k.connect(kg);kg.connect(master);k.start(t);k.stop(t+.13)}n++;window.pgMusicTimer=setTimeout(tick,step*1000*.92)};if(c.state==='suspended')c.resume();tick()}catch(e){}}
function startAmbient(){startFestivalMusic()}
function speakCongratulations(prize){try{if(!('speechSynthesis' in window))return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance('Congratulations! You have won '+prize+' from Planet G. Please collect your gift from our team. Thank you for your trust.');u.rate=.88;u.pitch=1.03;u.volume=1;const vs=speechSynthesis.getVoices();const v=vs.find(x=>/en-IN/i.test(x.lang))||vs.find(x=>/en/i.test(x.lang));if(v)u.voice=v;setTimeout(()=>speechSynthesis.speak(u),250)}catch(e){}}
function winnerHTML(prize){const imgs=prizeImages(prize).map(x=>'<img src="'+IMG[x]+'">').join('');return '<div class="winner"><div class="winnerStars"></div><div class="winnerTop"><div class="crown">👑</div><div class="congrats">CONGRATULATIONS!</div><div class="winnerRibbon">YOU WON!</div></div><div class="winnerProduct">'+imgs+'</div><div class="winnerPrize">'+prize+'</div><div class="winnerCollect">🎁 Please collect your gift from our Planet G team.</div><div class="winnerThanks">Thank You For Your Trust ❤️</div></div>'}
function shuffleSound(){try{const A=window.AudioContext||window.webkitAudioContext,c=new A();let t=c.currentTime;for(let i=0;i<22;i++){let o=c.createOscillator(),g=c.createGain();o.type='triangle';o.frequency.value=160+i*18;g.gain.setValueAtTime(.0001,t+i*.075);g.gain.exponentialRampToValueAtTime(.08,t+i*.075+.015);g.gain.exponentialRampToValueAtTime(.0001,t+i*.075+.06);o.connect(g);g.connect(c.destination);o.start(t+i*.075);o.stop(t+i*.075+.07)}}catch(e){}}
async function choose(i){if(locked)return;locked=true;document.querySelectorAll('.gift').forEach(x=>x.onclick=null);startAmbient();try{const r=await fetch('/api/customer/claim',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:sessionToken})});const d=await r.json();if(!r.ok)throw Error(d.error);stage.textContent='🎉 Congratulations!';grid.innerHTML=winnerHTML(d.prize);result.innerHTML='';confetti();speakCongratulations(d.prize)}catch(e){locked=false;result.innerHTML='<div class="err">'+e.message+'</div>'}}
function confetti(){const box=document.createElement('div');box.style='position:fixed;inset:0;pointer-events:none;z-index:50;overflow:hidden';for(let i=0;i<80;i++){let p=document.createElement('i');p.style='position:absolute;left:'+Math.random()*100+'%;top:-20px;width:8px;height:14px;background:'+['#c71925','#e4b332','#111','#fff'][i%4]+';animation:fall 2.5s linear forwards;animation-delay:'+(Math.random()*.5)+'s';box.appendChild(p)}document.body.appendChild(box);setTimeout(()=>box.remove(),3200)}
</script></body></html>`;

async function hmac(text){const k=await crypto.subtle.importKey('raw',new TextEncoder().encode('PLANETG-DASARA-2026-OTP-SECRET'),{name:'HMAC',hash:'SHA-256'},false,['sign']);const b=await crypto.subtle.sign('HMAC',k,new TextEncoder().encode(text));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function otpFor(mobile,tier,bucket){const h=await hmac(mobile+'|'+tier+'|'+bucket);return String(parseInt(h.slice(0,10),16)%1000000).padStart(6,'0')}
async function tokenFor(obj){const raw=btoa(unescape(encodeURIComponent(JSON.stringify(obj))));const sig=await hmac(raw);return raw+'.'+sig}
async function verifyToken(tok){const [raw,sig]=String(tok||'').split('.');if(!raw||!sig||await hmac(raw)!==sig)throw Error('Invalid session.');return JSON.parse(decodeURIComponent(escape(atob(raw))))}

export default {async fetch(request){const u=new URL(request.url);
 if(request.method==='GET'&&(u.pathname==='/'||u.pathname==='/play'||u.pathname==='/customer'))return new Response(PLAY_HTML,{headers:{'content-type':'text/html;charset=UTF-8'}});
 if(request.method==='GET'&&(u.pathname==='/staff'||u.pathname==='/staff.html'))return new Response(STAFF_HTML,{headers:{'content-type':'text/html;charset=UTF-8'}});
 if(u.pathname==='/api/health')return Response.json({ok:true,service:'Planet G Dasara Gift Game'});
 if(request.method!=='POST')return new Response('Not found',{status:404});
 if(u.pathname==='/api/staff/session'){const b=await request.json(),m=String(b.mobile||'').replace(/\D/g,''),a=Number(b.billValue);if(!b.customerName||m.length!==10||!b.billNumber||!Number.isFinite(a)||a<5000)return Response.json({error:'Enter valid details and a bill value of at least ₹5,000.'},{status:400});const t=tierFor(a),bucket=Math.floor(Date.now()/600000),otp=await otpFor(m,t.tier,bucket),token=await tokenFor({mobile:m,tier:t.tier,gifts:t.gifts,bucket,exp:Date.now()+600000});return Response.json({ok:true,otp,tier:t.tier,token});}
 if(u.pathname==='/api/customer/verify'){try{const b=await request.json(),m=String(b.mobile||'').replace(/\D/g,''),o=String(b.otp||'');if(m.length!==10||o.length!==6)throw Error('Invalid mobile number or OTP.');const now=Math.floor(Date.now()/600000);let match=null;for(const t of [tierFor(5000),tierFor(10000),tierFor(20000),tierFor(35000),tierFor(60001),tierFor(100000)])for(const buck of [now,now-1])if(await otpFor(m,t.tier,buck)===o)match={mobile:m,tier:t.tier,gifts:t.gifts,bucket:buck,exp:Date.now()+300000};if(!match)throw Error('Incorrect or expired OTP.');return Response.json({ok:true,token:await tokenFor(match)});}catch(e){return Response.json({error:e.message},{status:401})}}
 if(u.pathname==='/api/customer/claim'){try{const s=await verifyToken((await request.json()).token);if(s.exp<Date.now())throw Error('Session expired. Please ask staff for a new OTP.');const prize=s.gifts[Math.floor(Math.random()*s.gifts.length)];return Response.json({ok:true,prize});}catch(e){return Response.json({error:e.message},{status:400})}}
 return new Response('Not found',{status:404});
}};
